Types de données.exemple:
CREATE TABLE Exemple (
  moyenne DECIMAL(4,2)   -- de -99.99 à 99.99
);

CREATE TABLE Exemple (
  codePostal CHAR(4)     -- toujours 4 caractères
);

CREATE TABLE Exemple (
  nom VARCHAR(30)        -- 30 caractères au maximum
);

CREATE TABLE Exemple (
  dateEmprunt DATETIME  -- 'AAAA-MM-JJ HH:MM:SS'
);

CREATE TABLE Eleve (
  idEleve INT PRIMARY KEY,
  sexe ENUM('F', 'G')
);

Opérateurs de comparaison.exemple:
SELECT nom, moyenne FROM Eleve
WHERE moyenne BETWEEN 10 AND 12;

SELECT * FROM Emprunt
WHERE dateEmprunt BETWEEN '2026-10-01' AND '2026-10-31';

Opérateurs logiques.exemple:
SELECT nom FROM Eleve
WHERE NOT (ville = 'Tunis');

SELECT titre FROM Livre
WHERE idLivre NOT IN (SELECT idLivre FROM Emprunt);

Fonctions définies sur le type date.exemple:
SELECT idLivre, DATEDIFF(DATE(NOW()), dateEmprunt) AS joursEmprunt
FROM Emprunt
WHERE dateRetour IS NULL;

Manipulation des données.exemple:
DELETE FROM Emprunt
WHERE dateRetour IS NOT NULL
  AND YEAR(dateRetour) < 2025;

Contraintes d'intégrité.exemple:
CREATE TABLE Eleve (
  idEleve INT PRIMARY KEY,
  nom VARCHAR(30) NOT NULL
);

CREATE TABLE Eleve (
  idEleve INT PRIMARY KEY,
  ville VARCHAR(30) DEFAULT 'Manouba'
);

CREATE TABLE Eleve (
  idEleve INT PRIMARY KEY,
  moyenne DECIMAL(4,2) CHECK (moyenne BETWEEN 0 AND 20)
);

CREATE TABLE Eleve (
  idEleve INT,
  idClasse VARCHAR(10),
  CONSTRAINT pk_eleve PRIMARY KEY (idEleve),
  CONSTRAINT fk_eleve_classe FOREIGN KEY (idClasse) REFERENCES Classe(idClasse)
);

CREATE TABLE Eleve (
  idEleve INT PRIMARY KEY,
  email VARCHAR(60) UNIQUE
);

CREATE TABLE Eleve (
  idEleve INT,
  idClasse VARCHAR(10),
  CONSTRAINT pk_eleve PRIMARY KEY (idEleve),
  CONSTRAINT fk_eleve_classe FOREIGN KEY (idClasse) REFERENCES Classe(idClasse)
);

CREATE TABLE Eleve (
  idEleve INT,
  idClasse VARCHAR(10),
  CONSTRAINT pk_eleve PRIMARY KEY (idEleve),
  FOREIGN KEY (idClasse) REFERENCES Classe(idClasse)
);

Définition des données.exemple:
-- Syntaxe de l'annexe :
-- ALTER TABLE Eleve ALTER nom VARCHAR(50);

-- Forme exécutable sous MySQL :
ALTER TABLE Eleve CHANGE nom nom VARCHAR(50);

-- Renommer la table :
ALTER TABLE Eleve RENAME TO Eleves;

-- Renommer une colonne (MySQL) :
ALTER TABLE Eleve CHANGE prenom prenomEleve VARCHAR(30);

ALTER TABLE Eleve
ADD CONSTRAINT fk_eleve_classe
FOREIGN KEY (idClasse) REFERENCES Classe(idClasse);

ALTER TABLE Eleve ADD CONSTRAINT ck_moy CHECK (moyenne BETWEEN 0 AND 20);

